418	/// Breaks a styled line into lines no wider than `width`, after a space or `/` where possible (paths and headings).
419	fn wrap_line(line: Line<'static>, width: usize) -> Vec<Line<'static>> {
420	    let width = width.max(1);
421	    // Characters with their styles, then the break points chosen on the plain text.
422	    let cells: Vec<(char, Style)> = line.spans.iter().flat_map(|span| span.content.chars().map(move |c| (c, span.style))).collect();
423	    let text: String = cells.iter().map(|(c, _)| *c).collect();
424	    let rows = diff_view::wrap_at_breaks(&text, width);
425	    let mut out = Vec::new();
426	    let mut at = 0;
427	    for row in rows {
428	        // Skip the spaces a break consumed.
429	        while at < cells.len() && cells[at].0 == ' ' && !row.starts_with(' ') {
430	            at += 1;
431	        }
432	        let count = row.chars().count();
433	        let mut spans: Vec<Span<'static>> = Vec::new();
434	        for (c, style) in &cells[at..(at + count).min(cells.len())] {
435	            match spans.last_mut() {
436	                Some(last) if last.style == *style => last.content.to_mut().push(*c),
437	                _ => spans.push(Span::styled(c.to_string(), *style)),
438	            }
439	        }
440	        at += count;
441	        out.push(Line::from(spans));
442	    }
443	    out
444	}
