547	/// A modal rectangle at the top of `area`: one column of margin each side, at most `max_width` wide and
548	/// `wanted_height` tall, centred horizontally.
549	fn modal(area: Rect, max_width: u16, wanted_height: u16) -> Rect {
550	    let width = area.width.saturating_sub(2).min(max_width);
551	    let height = area.height.min(wanted_height);
552	    Rect::new(area.x + (area.width - width) / 2, area.y, width, height)
553	}
