773	fn line_style(kind: LineKind) -> Style {
774	    match kind {
775	        LineKind::Added => Style::default().fg(Color::Green),
776	        LineKind::Removed => Style::default().fg(Color::Red),
777	        LineKind::Hunk => Style::default().fg(Color::Cyan),
778	        LineKind::Meta => Style::default().fg(MUTED),
779	        LineKind::Command => Style::default()
780	            .fg(Color::White)
781	            .add_modifier(Modifier::BOLD),
782	        LineKind::Context => Style::default().fg(Color::White),
