786	/// How a row of a command's `diff` output is coloured: rows that are not part of a hunk read as headers.
787	fn diff_row_kind(row: &str) -> LineKind {
788	    if row.starts_with('+') && !row.starts_with("+++") {
789	        LineKind::Added
790	    } else if row.starts_with('-') && !row.starts_with("---") {
791	        LineKind::Removed
792	    } else if row.starts_with("@@") {
793	        LineKind::Hunk
794	    } else if row.starts_with(' ') {
795	        LineKind::Context
796	    } else {
797	        LineKind::Meta
798	    }
799	}
