    buttons.extend(button("Approve", Verdict::Approved, "y"));
    buttons.extend(button(if narrow { "All later" } else { "Approve all later actions" }, Verdict::ApprovedForSession, "a"));
    buttons.extend(button("Deny", Verdict::Denied, "n"));
