129	fn hunk_header(line: &str) -> Option<Hunk> {
130	    let rest = line.strip_prefix("@@ -")?;
131	    let (ranges, section) = rest.split_once(" @@").unwrap_or((rest, ""));
132	    let (old, new) = ranges.split_once(" +")?;
133	    let range = |text: &str| -> Option<(u32, u32)> {
134	        match text.split_once(',') {
135	            Some((start, count)) => Some((start.parse().ok()?, count.parse().ok()?)),
136	            None => Some((text.parse().ok()?, 1)),
137	        }
138	    };
139	    let (old_start, old_count) = range(old)?;
140	    let (new_start, new_count) = range(new)?;
141	    Some(Hunk { old_start, old_count, new_start, new_count, section: section.trim().to_string(), lines: Vec::new() })
142	}
