144	/// Parses a unified diff (git's or the sidecar's). Hunk bodies are read by their counts, so a removed line whose
145	/// text starts with `-- ` is never mistaken for a file header.
146	pub fn parse(text: &str) -> Patch {
147	    let mut patch = Patch::default();
148	    let mut current: Option<FilePatch> = None;
149	    // Lines still owed by the open hunk (old side, new side), and the next line numbers.
150	    let mut owed = (0u32, 0u32);
151	    let mut next = (0u32, 0u32);
152	    for raw in text.split('\n') {
153	        let mut line = raw;
154	        if let Some(at) = raw.find("…[truncated ")
155	            && raw.ends_with(" chars]")
156	        {
157	            patch.truncated = Some(raw[at..].to_string());
158	            line = &raw[..at];
159	            if line.is_empty() {
160	                continue;
161	            }
162	        }
163	        if owed != (0, 0)
164	            && let Some(file) = current.as_mut()
165	            && let Some(hunk) = file.hunks.last_mut()
166	        {
167	            let (kind, body) = match line.chars().next() {
168	                Some(' ') => (Some(Kind::Context), &line[1..]),
169	                None => (Some(Kind::Context), ""),
170	                Some('-') => (Some(Kind::Removed), &line[1..]),
171	                Some('+') => (Some(Kind::Added), &line[1..]),
172	                Some('\\') => {
173	                    if let Some(last) = hunk.lines.last_mut() {
174	                        last.no_eol = true;
175	                    }
176	                    continue;
177	                }
178	                _ => (None, ""),
179	            };
180	            if let Some(kind) = kind {
181	                let old = (kind != Kind::Added).then_some(next.0);
182	                let new = (kind != Kind::Removed).then_some(next.1);
183	                if kind != Kind::Added {
184	                    next.0 += 1;
185	                    owed.0 = owed.0.saturating_sub(1);
186	                }
187	                if kind != Kind::Removed {
188	                    next.1 += 1;
189	                    owed.1 = owed.1.saturating_sub(1);
190	                }
191	                hunk.lines.push(DLine { kind, old, new, text: body.to_string(), no_eol: false });
192	                continue;
193	            }
194	            owed = (0, 0);
195	        }
196	        if line.starts_with('\\') {
197	            // The marker after a hunk's last line, once its counts are satisfied.
198	            if let Some(last) = current.as_mut().and_then(|f| f.hunks.last_mut()).and_then(|h| h.lines.last_mut()) {
199	                last.no_eol = true;
200	            }
201	            continue;
202	        }
203	        if let Some(rest) = line.strip_prefix("diff --git ") {
204	            patch.files.extend(current.take());
205	            let mut file = FilePatch::new(Status::Modified);
206	            if let Some((a, b)) = rest.rsplit_once(" b/") {
207	                file.old_path = strip_prefix(a, "a/");
208	                file.new_path = Some(b.to_string());
209	            }
210	            current = Some(file);
211	        } else if let Some(rest) = line.strip_prefix("--- ") {
212	            if current.as_ref().is_none_or(|f| f.saw_old_header || !f.hunks.is_empty()) {
213	                patch.files.extend(current.take());
214	                current = Some(FilePatch::new(Status::Modified));
215	            }
216	            let file = current.as_mut().expect("a file section is open");
217	            file.saw_old_header = true;
218	            file.old_path = strip_prefix(rest, "a/");
219	            if file.old_path.is_none() {
220	                file.status = Status::Added;
221	            }
222	        } else if let Some(rest) = line.strip_prefix("+++ ") {
223	            let file = current.get_or_insert_with(|| FilePatch::new(Status::Modified));
224	            file.new_path = strip_prefix(rest, "b/");
225	            if file.new_path.is_none() {
226	                file.status = Status::Deleted;
227	            }
228	        } else if line.starts_with("@@ ") {
229	            if let Some(hunk) = hunk_header(line) {
230	                owed = (hunk.old_count, hunk.new_count);
231	                next = (hunk.old_start.max(1), hunk.new_start.max(1));
232	                if hunk.old_count == 0 {
233	                    next.0 = hunk.old_start + 1;
234	                }
235	                if hunk.new_count == 0 {
236	                    next.1 = hunk.new_start + 1;
237	                }
238	                current.get_or_insert_with(|| FilePatch::new(Status::Modified)).hunks.push(hunk);
239	            }
240	        } else if let Some(file) = current.as_mut() {
241	            if line.starts_with("new file mode") {
242	                file.status = Status::Added;
243	                file.old_path = None;
244	            } else if line.starts_with("deleted file mode") {
245	                file.status = Status::Deleted;
246	                file.new_path = None;
247	            } else if let Some(from) = line.strip_prefix("rename from ") {
248	                file.status = Status::Renamed;
249	                file.old_path = Some(from.to_string());
250	            } else if let Some(to) = line.strip_prefix("rename to ") {
251	                file.status = Status::Renamed;
252	                file.new_path = Some(to.to_string());
253	            } else if line.starts_with("Binary files ") || line.starts_with("GIT binary patch") {
254	                file.notes.push("binary file — no line diff".to_string());
255	            }
256	        }
257	    }
258	    patch.files.extend(current);
259	    patch
260	}
