1116	fn wrap_spans(line: Line<'static>, width: usize) -> Vec<Line<'static>> {
1117	    let width = width.max(1);
1118	    let mut out: Vec<Line<'static>> = vec![Line::default()];
1119	    let mut used = 0;
1120	    for span in line.spans {
1121	        let mut piece = String::new();
1122	        for grapheme in span.content.graphemes(true) {
1123	            let w = UnicodeWidthStr::width(grapheme);
1124	            if used + w > width && used > 0 {
1125	                if !piece.is_empty() {
1126	                    out.last_mut().expect("a line is open").spans.push(Span::styled(std::mem::take(&mut piece), span.style));
1127	                }
1128	                out.push(Line::default());
1129	                used = 0;
1130	            }
1131	            piece.push_str(grapheme);
1132	            used += w;
1133	        }
1134	        if !piece.is_empty() {
1135	            out.last_mut().expect("a line is open").spans.push(Span::styled(piece, span.style));
1136	        }
1137	    }
1138	    out
1139	}
