499	/// Splits content cells into rows of at most `width` columns. Wrapping breaks after a space when one falls in the
500	/// latter two thirds of the row (the space stays at the row's end, so no character is lost), else at the edge.
501	fn fit_rows(cells: Vec<Cell>, width: usize, fit: Fit) -> Vec<Vec<Cell>> {
502	    match fit {
503	        Fit::Wrap => {
504	            let mut rows: Vec<Vec<Cell>> = vec![Vec::new()];
505	            let mut used = 0;
506	            for cell in cells {
507	                if used + cell.width > width && used > 0 {
508	                    let row = rows.last_mut().expect("a row is open");
509	                    let mut carried = Vec::new();
510	                    if cell.text != " " {
511	                        let mut at = 0;
512	                        let mut space = None;
513	                        for (index, c) in row.iter().enumerate() {
514	                            at += c.width;
515	                            if c.text == " " && at * 3 > width {
516	                                space = Some(index);
517	                            }
518	                        }
519	                        if let Some(index) = space {
520	                            carried = row.split_off(index + 1);
521	                        }
522	                    }
523	                    used = carried.iter().map(|c| c.width).sum();
524	                    rows.push(carried);
525	                }
526	                used += cell.width;
527	                rows.last_mut().expect("a row is open").push(cell);
528	            }
529	            rows
530	        }
531	        Fit::Clip(left) => {
532	            let total: usize = cells.iter().map(|c| c.width).sum();
533	            let right = left + width;
534	            let mut row = Vec::new();
535	            let mut col = 0;
536	            for cell in cells {
537	                let (start, end) = (col, col + cell.width);
538	                col = end;
539	                if end <= left || (cell.width == 0 && start < left) {
540	                    continue;
541	                }
542	                if start < left {
543	                    // A wide character cut by the left edge: its visible half becomes blank.
544	                    row.push(spaces((end - left).min(width)));
545	                    continue;
546	                }
547	                if end > right {
548	                    if start < right {
549	                        row.push(spaces(right - start));
550	                    }
551	                    break;
552	                }
553	                row.push(cell);
554	            }
555	            let mut used: usize = row.iter().map(|c| c.width).sum();
556	            if total > right && width > 1 {
557	                while used > width - 1 {
558	                    let last = row.pop().expect("cells fill the row");
559	                    used -= last.width;
560	                }
561	                if used < width - 1 {
562	                    row.push(spaces(width - 1 - used));
563	                }
564	                row.push(Cell { text: "›".into(), width: 1, token: None });
565	            }
566	            if left > 0 && total > 0 && width > 1 {
567	                let mut removed = 0;
568	                while removed < 1 && !row.is_empty() {
569	                    removed += row.remove(0).width;
570	                }
571	                if removed > 1 {
572	                    row.insert(0, spaces(removed - 1));
573	                }
574	                row.insert(0, Cell { text: "‹".into(), width: 1, token: None });
575	            }
576	            vec![row]
577	        }
578	    }
579	}
